async def act(page):
    """Locate the requested post using the site-aware search helper and leave the comment.

    Steps:
    1. Use create_curated_collection_by_search(...) to locate the post via the visible search UI.
    2. If found, navigate to the post URL (resolved against page.url).
    3. Locate the comment textbox using accessibility-role-centric selectors (prefer fields whose
       attributes indicate they are comment inputs or TEXTAREA elements) and fill the requested comment.
    4. Best-effort fill name and email fields if present.
    5. Submit the comment by clicking an accessible submit button inside the main container (use
       the full get_by_role path when possible). Clicking a submit button is the final action.

    Notes:
    - Uses create_curated_collection_by_search from the knowledge base (it navigates to '/' as its first action).
    - All locator indexing is guarded by await locator.count() before using .nth() or .first().
    - Fragile DOM reads are wrapped in small try/except blocks.
    """
    import urllib.parse

    target_title = (
        "Rivalries And Rumours: How The New Order Of The Murdoch Dynasty Is Playing Out"
    )
    comment_text = "Well written and easy to understand."

    # 1) Use the site-aware search helper to find the post (helper will navigate to '/')
    try:
        results = await create_curated_collection_by_search(page, keyword=target_title, max_results=50)
    except Exception:
        results = []

    post_href = None

    # 2) Inspect helper results for a matching title
    if isinstance(results, list):
        for item in results:
            if not isinstance(item, dict):
                continue
            title = (item.get("title") or "").strip()
            href = item.get("url") or ""
            if title and target_title.lower() in title.lower():
                post_href = href
                break

    # 2b) Fallback: broader search if exact-title search fails
    if not post_href:
        try:
            fallback_results = await create_curated_collection_by_search(page, keyword="Murdoch", max_results=50)
        except Exception:
            fallback_results = []
        if isinstance(fallback_results, list):
            for item in fallback_results:
                if not isinstance(item, dict):
                    continue
                title = (item.get("title") or "").strip()
                href = item.get("url") or ""
                if title and ("murdoch" in title.lower() or "rivalries" in title.lower()):
                    post_href = href
                    break

    # 2c) Final fallback: scan visible links on the currently-loaded page
    if not post_href:
        link_locator = page.get_by_role("link")
        try:
            link_count = await link_locator.count()
        except Exception:
            link_count = 0
        for i in range(link_count):
            try:
                text = (await link_locator.nth(i).inner_text()) or ""
            except Exception:
                text = ""
            low = text.lower()
            if any(tok in low for tok in ("murdoch", "rivalries", "new order")) or target_title.lower() in low:
                try:
                    href = await link_locator.nth(i).get_attribute("href")
                except Exception:
                    href = None
                if href:
                    post_href = href
                    break

    # If we couldn't find the post, stop.
    if not post_href:
        return

    # 3) Resolve and navigate to the post URL
    resolved = urllib.parse.urljoin(page.url, post_href)
    await page.goto(resolved)

    # Best-effort wait for main content to appear and scope subsequent lookups there
    try:
        main = page.get_by_role("main")
        if await main.count():
            await main.first.wait_for(state="visible", timeout=5000)
            container = main.first
        else:
            container = page
    except Exception:
        container = page

    # 4) Locate the comment textbox using role-based selectors
    comment_locator = None
    try:
        tb_locator = container.get_by_role("textbox")
        tb_count = await tb_locator.count()
    except Exception:
        tb_locator = page.get_by_role("textbox")
        try:
            tb_count = await tb_locator.count()
        except Exception:
            tb_count = 0

    for i in range(tb_count):
        loc = tb_locator.nth(i)
        try:
            name_attr = (await loc.get_attribute("name")) or ""
        except Exception:
            name_attr = ""
        try:
            aria = (await loc.get_attribute("aria-label")) or ""
        except Exception:
            aria = ""
        try:
            placeholder = (await loc.get_attribute("placeholder")) or ""
        except Exception:
            placeholder = ""
        combined = (name_attr + " " + aria + " " + placeholder).lower()
        # Prefer explicit comment fields
        if "comment" in combined or "leave a comment" in combined or "your comment" in combined:
            comment_locator = loc
            break
        # Prefer TEXTAREA elements
        try:
            tag = await loc.evaluate("el => el.tagName")
        except Exception:
            tag = ""
        if tag and tag.lower() == "textarea":
            comment_locator = loc
            break

    # Named fallback
    if not comment_locator:
        try:
            named = container.get_by_role("textbox", name="Comment")
            if await named.count():
                comment_locator = named.first
        except Exception:
            pass

    # 5) Fill the comment textbox if found
    if comment_locator is not None:
        try:
            await comment_locator.fill(comment_text)
        except Exception:
            try:
                await comment_locator.focus()
                await page.keyboard.type(comment_text)
            except Exception:
                pass

    # 6) Best-effort: find and fill name and email fields
    name_field = None
    try:
        candidate = container.get_by_role("textbox", name="Name")
        if await candidate.count():
            name_field = candidate.first
    except Exception:
        name_field = None

    if name_field is None:
        scan = container.get_by_role("textbox")
        try:
            scan_count = await scan.count()
        except Exception:
            scan = page.get_by_role("textbox")
            try:
                scan_count = await scan.count()
            except Exception:
                scan_count = 0
        for i in range(scan_count):
            loc = scan.nth(i)
            try:
                n = (await loc.get_attribute("name")) or ""
            except Exception:
                n = ""
            try:
                a = (await loc.get_attribute("aria-label")) or ""
            except Exception:
                a = ""
            try:
                p = (await loc.get_attribute("placeholder")) or ""
            except Exception:
                p = ""
            combined = (n + " " + a + " " + p).lower()
            if any(k in combined for k in ("name", "author", "your name")) and "comment" not in combined:
                name_field = loc
                break

    if name_field is not None:
        try:
            await name_field.fill("Commenter")
        except Exception:
            pass

    email_field = None
    try:
        candidate_e = container.get_by_role("textbox", name="Email")
        if await candidate_e.count():
            email_field = candidate_e.first
    except Exception:
        email_field = None

    if email_field is None:
        scan2 = container.get_by_role("textbox")
        try:
            scan_count2 = await scan2.count()
        except Exception:
            scan2 = page.get_by_role("textbox")
            try:
                scan_count2 = await scan2.count()
            except Exception:
                scan_count2 = 0
        for i in range(scan_count2):
            loc = scan2.nth(i)
            try:
                n = (await loc.get_attribute("name")) or ""
            except Exception:
                n = ""
            try:
                a = (await loc.get_attribute("aria-label")) or ""
            except Exception:
                a = ""
            try:
                p = (await loc.get_attribute("placeholder")) or ""
            except Exception:
                p = ""
            if "email" in (n + a + p).lower():
                email_field = loc
                break

    if email_field is not None:
        try:
            await email_field.fill("commenter@example.com")
        except Exception:
            pass

    # 7) Submit the comment. Use container.get_by_role(...) for buttons when possible.
    submitted = False
    common_button_names = ["Post Comment", "Submit Comment", "Submit", "Comment", "Post"]

    try:
        for name in common_button_names:
            try:
                btn = container.get_by_role("button", name=name)
                if await btn.count():
                    # Click is last action if it navigates away
                    await btn.first.click()
                    submitted = True
                    break
            except Exception:
                pass
    except Exception:
        pass

    if not submitted:
        try:
            btns = container.get_by_role("button")
            btn_count = await btns.count()
        except Exception:
            btns = page.get_by_role("button")
            try:
                btn_count = await btns.count()
            except Exception:
                btn_count = 0
        for i in range(btn_count):
            loc = btns.nth(i)
            try:
                text = (await loc.inner_text()).strip().lower()
            except Exception:
                text = ""
            if any(tok in text for tok in ("comment", "post", "submit")):
                try:
                    await loc.click()
                    submitted = True
                    break
                except Exception:
                    pass

    return

